def factorize(n: int) -> List[int]:
    """Extract prime factors in ascending order by trial division."""
    remaining_value = n
    candidate_factor = 2
    prime_factors = []
    while candidate_factor * candidate_factor <= remaining_value:
        if remaining_value % candidate_factor == 0:
            prime_factors.append(candidate_factor)
            remaining_value //= candidate_factor
